const raw = String($json.Brands ?? $json.brands ?? '').trim();
if (!raw) throw new Error('Brands list is empty');

const lines = raw.split(/\r?\n/).map(s => s.trim()).filter(Boolean);
const rows = [];
const invalid = [];
const allowed = ['US','CA','AU','UK','NL','DE','FR'];

for (const line of lines) {
  const parts = line.split('|').map(s => s.trim());
  if (parts.length !== 3 || !parts[0] || !parts[1] || !parts[2]) {
    invalid.push(line);
    continue;
  }

  const [brand, domain, countryRaw] = parts;
  const country = countryRaw.toUpperCase() === 'GB' ? 'UK' : countryRaw.toUpperCase();

  if (!allowed.includes(country)) {
    invalid.push(line + ' [unsupported country]');
    continue;
  }

  rows.push({
    brand,
    website: /^https?:\/\//i.test(domain) ? domain : 'https://' + domain + '/',
    countries: [country]
  });
}

if (!rows.length) throw new Error('No valid rows. Use: Brand|domain|country');
if (invalid.length) throw new Error('Invalid rows: ' + invalid.join(' ; '));

const batchJson = JSON.stringify(rows);

return [{
  json: {
    brandCount: rows.length,
    brands: rows.map(x => ({
      brand: x.brand,
      domain: String(x.website)
        .replace(/^https?:\/\//i, '')
        .replace(/^www\./i, '')
        .replace(/\/.*$/, ''),
      country: x.countries[0]
    })),
    batchBase64: Buffer.from(batchJson, 'utf8').toString('base64')
  }
}];

const raw = $json.stdout;
if (!raw) throw new Error('Serper search returned empty stdout');

const data = JSON.parse(raw);
const sourceRows = $('Prepare Brand List').first().json.brands ?? [];
const expected = Number($('Prepare Brand List').first().json.brandCount ?? sourceRows.length);

if ((data.searches ?? []).length !== expected) {
  const got = (data.searches ?? []).map(x => x.brand).join(', ');
  const failed = (data.failures ?? []).map(x => `${x.brand} (${x.country}): ${x.error}`).join(' | ');
  throw new Error(`Expected ${expected} brand searches but got ${(data.searches ?? []).length}. Returned: ${got || 'none'}. Failures: ${failed || 'none'}`);
}

const domainMap = new Map(
  sourceRows.map(x => [String(x.brand).trim().toLowerCase(), x.domain])
);

return (data.searches ?? []).map(search => ({
  json: {
    brand: search.brand,
    domain: domainMap.get(String(search.brand).trim().toLowerCase()) ?? '',
    country: search.country,
    results: search.results ?? [],
    resultCount: (search.results ?? []).length,
    failures: (data.failures ?? []).filter(f => f.brand === search.brand && f.country === search.country)
  }
}));

return $input.all().map(({ json: item }) => {
const brand = item.brand;
const domain = item.domain;
const country = item.country;
const urls = (item.results ?? []).map(x => x.url).filter(Boolean).slice(0, 10);

const numbered = urls.map((u, i) => `${i + 1}. ${u}`).join('\n');

const prompt = `You are extracting coupon codes for ${brand} (${domain}) in ${country}.

IMPORTANT RULES:
- Use ONLY the supplied URLs below. Do not use Google or discover additional URLs.
- Audit every supplied URL.
- Extract up to the first 10 UNIQUE coupon/promo codes per URL.
- Preserve codes exactly as displayed, including unusual capitalization, punctuation, numbers, or symbols.
- If a coupon card has Show Code / Get Code / Reveal / View Code / Unlock / Copy Code, interact with it and inspect the resulting popup, modal, same-page reveal, clipboard value, or newly opened tab.
- If clicking redirects to the merchant, return to the coupon source and continue inspecting the coupon source itself.
- Ignore expired offers when clearly marked expired.
- For the official merchant website, only return an explicit coupon/promo code. A sale or percentage discount without an explicit code is NOT a coupon code.
- If a page is blocked, CAPTCHA-protected, login-only, or inaccessible, return status "blocked" or "skipped"; never silently omit the URL.
- If a URL has zero valid codes, return that source once with status="no_code" and codes=[]. Do not create blank or fake coupon codes.
- Do NOT validate codes at checkout.
- Do not invent codes.

Return ONLY JSON in this schema:
{
  "brand": "${brand}",
  "country": "${country}",
  "sources": [
    {
      "source_url": "https://...",
      "status": "extracted|no_code|blocked|skipped|error",
      "codes": ["CODE1","CODE2"]
    }
  ]
}

SUPPLIED URLS:
${numbered}`;

return { json: { ...item, couponPrompt: prompt } };
});

return $input.all().map(({ json: item }) => {
const brand = item.brand;
const domain = item.domain;
const country = item.country;
const website = /^https?:\/\//i.test(domain) ? domain : `https://${domain}`;

const prompt = `Research current deals for ${brand} in ${country} using ONLY the official website: ${website}

TASKS:

1) SALE / CURRENT PROMOTION
- Find the official sale, offers, clearance, promotions, or deals section if one exists.
- Report the source URL.
- If individual products show both original and sale prices, calculate:
  - lowest sale price
  - highest sale price
  - minimum discount percentage
  - maximum discount percentage
- Only calculate a discount when the SAME product clearly shows both an original price and a sale price.
- Do not infer discounts from unrelated prices.
- If there is a stated promotion such as "20% off selected items", capture the exact meaning in concise text.

2) SHIPPING / DELIVERY OFFER
- Find any current free-shipping, free-delivery, threshold, or shipping promotion.
- Return the official source URL and concise deal text.
- If none is verified, set found=false.

3) NEWSLETTER / EMAIL / SMS / NEW-CUSTOMER OFFER
- Find any official signup discount or first-order/new-customer offer.
- Return the official source URL and concise deal text.
- If none is verified, set found=false.

RULES:
- Use ONLY ${website} and pages on that same official domain.
- Do not use coupon websites, Google snippets, Reddit, or third-party sources.
- Do not invent missing discounts or prices.
- If something cannot be verified, explicitly return null/false.

Return ONLY JSON:
{
  "brand": "${brand}",
  "country": "${country}",
  "website": "${website}",
  "sale": {
    "found": false,
    "source_url": "",
    "lowest_sale_price": null,
    "highest_sale_price": null,
    "currency": "",
    "min_discount_percent": null,
    "max_discount_percent": null,
    "deal_text": ""
  },
  "shipping": {
    "found": false,
    "source_url": "",
    "deal_text": ""
  },
  "newsletter": {
    "found": false,
    "source_url": "",
    "deal_text": ""
  }
}`;

return { json: { ...item, dealPrompt: prompt } };
});
